// Variables exported from FigCraft.

import 'dart:ui';

/// Theme · Light
abstract final class Theme {
  static const Color base = Color(0xC0C24681);
  static const Color accent = Color(0x60C24681);
  static const Color highlight = Color(0x84C24681);
  static const String action = 'Continue';
  static const bool enabled = true;
  static const double size = 48;
  static const double alpha = 40;
  static const double copyNumber = 23;
  static const double blurSize = 18;
  static const Color framePaint = Color(0xFFFF0000);
  static const Color shapePaint = Color(0xFF00FF00);
}

/// Theme · Dark
abstract final class ThemeDark {
  static const Color base = Color(0x801729BA);
  static const Color accent = Color(0x801729BA);
  static const Color highlight = Color(0x80B7AAA8);
  static const String action = '次へ';
  static const bool enabled = false;
  static const double size = 48;
  static const double alpha = 40;
  static const double copyNumber = 23;
  static const double blurSize = 18;
  static const Color framePaint = Color(0xFFFF0000);
  static const Color shapePaint = Color(0xFF00FF00);
}

/// Density · Compact
abstract final class Density {
  static const double spacing = 6.5;
}

/// Density · Comfortable
abstract final class DensityComfortable {
  static const double spacing = 13.75;
}

