/* Theme · Light */
:root {
  --base: rgba(194, 70, 129, 0.753);
  --accent: rgba(194, 70, 129, 0.375);
  --highlight: rgba(194, 70, 129, 0.517);
  --action: "Continue";
  --enabled: true;
  --size: 48px;
  --alpha: 40;
  --copy-number: 23px;
  --blur-size: 18px;
  --frame-paint: #FF0000;
  --shape-paint: #00FF00;
}
/* Theme · Dark */
[data-theme="Dark"] {
  --base: rgba(23, 41, 186, 0.50);
  --accent: var(--base);
  --highlight: rgba(183, 170, 168, 0.50);
  --action: "次へ";
  --enabled: false;
  --size: 48px;
  --alpha: 40;
  --copy-number: 23px;
  --blur-size: 18px;
  --frame-paint: #FF0000;
  --shape-paint: #00FF00;
}
/* Density · Compact */
:root {
  --spacing: 6.5px;
}
/* Density · Comfortable */
[data-density="Comfortable"] {
  --spacing: 13.75px;
}

